		if (value == null) {
			state = true;
			continue;
		}
		const expression = value.type === 'JSXExpressionContainer' ? value.expression : value;
		if (isDefinitelyNonNullishJsxExpression(expression)) state = true;
		else if (isDefinitelyNullishJsxExpression(expression)) state = false;
