		ctx.currentHookMemoNames = names = {
			cache: allocCompilerName(ctx, '__hk'),
			result: allocCompilerName(ctx, '__hkr'),
			label: allocCompilerName(ctx, '__hkl'),
			temps: [],
			expressionTemps: [],
		};
