			remainingRanges !== null &&
			node.type === 'JSXExpressionContainer' &&
			((key === 'children' &&
				(parent?.type === 'JSXElement' ||
					parent?.type === 'Element' ||
					parent?.type === 'JSXFragment' ||
					parent?.type === 'Fragment')) ||
				(key === 'render' && parent?.type === 'JSXCodeBlock'))
