		id,
		compNode,
		propsExpr,
		hostPath: null,
		keyExpr,
		liteEligible,
		anchorlessAppendSafe,
		autoMemoDeps,
		autoMemoDepNodes,
		autoMemoWitnesses,
		autoMemoContextAware,
		autoMemoLite,
		autoMemoPublicationWitnesses,
		voidComponent,
		singleRoot,
		maybeSingleRoot,
