		id: ctx.nextHelperId++,
		loc: devLoc(ctx, node),
		origin: node,
		envNames,
		tryHelper: tryHelperName,
		catchHelper: catchHelperName,
		pendingHelper: pendingHelperName,
		// `@catch` / `@pending` keywords — each clause starts at its own `{`.
		handlerKeyword: node.handlerKeyword ?? null,
